// WIRED 17 August 2026, task #116, Phase C.
//
// ── WHAT THIS REPLACED ───────────────────────────────────────────────────
//
// Two fixed cards — "The Riverside Apartment, 12 to 14 July, Richmond,
// CONFIRMED, In 12 days" and "Stow on the Wold, PENDING" — shown to every
// guest whether or not they had ever booked anything. The Past tab was
// `const Center(child: Text('No past bookings'))`, permanently. "View Details"
// had an empty handler.
//
// So a guest who had just booked saw somebody else's two trips and not their
// own, and could not open either.
//
// ── THE INDEX THIS NEEDED, WHICH DID NOT EXIST ───────────────────────────
//
// myBookings() filters on guestUid and orders by checkIn. That combination
// needs a composite index, and firestore.indexes.json had three stay_bookings
// indexes — all keyed on hostUid, built for the host app. The guest's own
// query had never had one, so it would have failed with FAILED_PRECONDITION
// the first time anybody opened this screen.
//
// Added guestUid + checkIn DESC. Same fault as mostPartnersNearby on the home
// screen: a guest-side query written weeks ago, never called, never indexed.
// ⚠ Needs DEPLOY_INDEXES.bat, and a new index takes minutes to build.
//
// ── WHY THE LISTINGS ARE FETCHED SEPARATELY ──────────────────────────────
//
// A booking stores listingId, not the title or the photo. Rather than one read
// per card, every id in the list goes through StayListingService.byIds, which
// chunks at 30 for whereIn. Ten bookings cost one extra query, not ten.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_booking.dart';
import '../models/stay_enums.dart';
import '../models/stay_listing.dart';
import '../services/stay_booking_service.dart';
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';

class MyBookingsScreen extends StatefulWidget {
  const MyBookingsScreen({super.key});

  @override
  State<MyBookingsScreen> createState() => _MyBookingsScreenState();
}

class _MyBookingsScreenState extends State<MyBookingsScreen> {
  /// listingId -> listing, filled as bookings arrive.
  final Map<String, StayListing> _listings = <String, StayListing>{};
  final Set<String> _requested = <String>{};

  /// Loads any listing referenced by a booking that has not been fetched.
  ///
  /// Guarded by _requested so a rebuilding stream does not re-query the same
  /// ids forever — the StreamBuilder can rebuild many times per second while
  /// Firestore settles.
  void _ensureListings(List<StayBooking> bookings) {
    final List<String> missing = bookings
        .map((b) => b.listingId)
        .where((id) => id.isNotEmpty && !_requested.contains(id))
        .toSet()
        .toList();
    if (missing.isEmpty) return;

    _requested.addAll(missing);
    _fetchListings(missing);
  }

  /// try/catch, not .catchError.
  ///
  /// This was `.then(...).catchError((_) => <StayListing>[])`, which the
  /// analyzer rejects: the `then` returns Future<void>, so the error handler
  /// must return void or null — a list is not assignable to it. Awaiting in a
  /// plain async method sidesteps the whole question and reads better.
  Future<void> _fetchListings(List<String> ids) async {
    try {
      final List<StayListing> found =
          await StayListingService.instance.byIds(ids);
      if (!mounted) return;
      setState(() {
        for (final l in found) {
          _listings[l.id] = l;
        }
      });
    } catch (_) {
      // Swallowed on purpose. The dates, status and reference all come from
      // the booking itself; a missing title is a worse card, not a broken one.
    }
  }

  @override
  Widget build(BuildContext context) {
    return DefaultTabController(
      length: 2,
      child: Scaffold(
        backgroundColor: GoOutsColors.background,
        appBar: AppBar(
          backgroundColor: Colors.white,
          elevation: 0.5,
          leading: IconButton(
            icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
            onPressed: () => Navigator.of(context).pop(),
          ),
          title: Text(
            'My Bookings',
            style: GoogleFonts.inter(
              fontSize: 20,
              fontWeight: FontWeight.bold,
              color: GoOutsColors.deepNavy,
            ),
          ),
          bottom: TabBar(
            indicatorColor: GoOutsColors.primaryBlue,
            indicatorWeight: 3,
            labelColor: GoOutsColors.primaryBlue,
            unselectedLabelColor: GoOutsColors.bodyText,
            labelStyle:
                GoogleFonts.inter(fontWeight: FontWeight.bold, fontSize: 16),
            tabs: const [
              Tab(text: 'Upcoming'),
              Tab(text: 'Past'),
            ],
          ),
        ),
        // The fake bottom navigation bar is gone. It rendered Search / Trips /
        // Rewards / Profile with no tap handling on a screen that is PUSHED,
        // not a tab — so it was four dead labels sitting under a real app.
        body: StreamBuilder<List<StayBooking>>(
          stream: StayBookingService.instance.myBookings(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(child: CircularProgressIndicator());
            }
            if (snapshot.hasError) {
              return _error(snapshot.error.toString());
            }

            final List<StayBooking> all =
                snapshot.data ?? const <StayBooking>[];
            _ensureListings(all);

            final DateTime today = DateTime.now();
            // "Upcoming" means the stay has not finished AND was not called
            // off. A cancelled trip next month belongs in Past — it is not
            // something the guest is going on.
            final upcoming = all
                .where((b) =>
                    !b.status.isCancelled &&
                    b.status != BookingStatus.declined &&
                    b.checkOut.isAfter(today))
                .toList()
              ..sort((a, b) => a.checkIn.compareTo(b.checkIn));

            final past = all.where((b) => !upcoming.contains(b)).toList()
              ..sort((a, b) => b.checkIn.compareTo(a.checkIn));

            return TabBarView(
              children: [
                _list(upcoming, emptyTitle: 'No trips booked yet',
                    emptyBody: 'When you book somewhere, it appears here with '
                        'everything you need for the stay.'),
                _list(past, emptyTitle: 'Nothing here yet',
                    emptyBody: 'Stays you have finished, and any you cancelled, '
                        'are kept here.'),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _error(String message) => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.cloud_off, size: 48,
                  color: GoOutsColors.primaryBlue),
              const SizedBox(height: 12),
              Text(
                'Your bookings could not be loaded',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy),
              ),
              const SizedBox(height: 8),
              // The real error, not "something went wrong". A failed-precondition
              // here means the guestUid + checkIn index has not finished
              // building, and that is worth being able to read rather than
              // guess at.
              Text(
                message,
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 12, color: GoOutsColors.bodyText),
              ),
            ],
          ),
        ),
      );

  Widget _list(List<StayBooking> bookings,
      {required String emptyTitle, required String emptyBody}) {
    if (bookings.isEmpty) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.luggage_outlined,
                  size: 48, color: GoOutsColors.primaryBlue),
              const SizedBox(height: 12),
              Text(
                emptyTitle,
                style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy),
              ),
              const SizedBox(height: 6),
              Text(
                emptyBody,
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.bodyText),
              ),
            ],
          ),
        ),
      );
    }

    return ListView.separated(
      padding: const EdgeInsets.all(16),
      itemCount: bookings.length,
      separatorBuilder: (_, __) => const SizedBox(height: 16),
      itemBuilder: (context, i) => _bookingCard(bookings[i]),
    );
  }

  // ── Status ───────────────────────────────────────────────────────────────
  //
  // Every status the enum can hold gets a label and a colour. A switch with no
  // default means adding a status to BookingStatus breaks the build here
  // rather than rendering a blank chip.
  ({String label, Color colour}) _statusChip(BookingStatus s) {
    switch (s) {
      case BookingStatus.pending:
        return (label: 'AWAITING HOST', colour: GoOutsColors.pendingOrange);
      case BookingStatus.confirmed:
        return (label: 'CONFIRMED', colour: GoOutsColors.successGreen);
      case BookingStatus.inProgress:
        return (label: 'YOU ARE THERE', colour: GoOutsColors.primaryBlue);
      case BookingStatus.completed:
        return (label: 'COMPLETED', colour: GoOutsColors.bodyText);
      case BookingStatus.declined:
        return (label: 'DECLINED', colour: GoOutsColors.error);
      case BookingStatus.cancelledGuest:
        return (label: 'YOU CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.cancelledHost:
        return (label: 'HOST CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.disputed:
        return (label: 'UNDER REVIEW', colour: GoOutsColors.warning);
    }
  }

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  /// "12 to 14 July" when one month, "30 July to 2 August" when it spans two.
  static String _dateRange(DateTime a, DateTime b) => a.month == b.month
      ? '${a.day} to ${b.day} ${_months[b.month - 1]}'
      : '${a.day} ${_months[a.month - 1]} to ${b.day} ${_months[b.month - 1]}';

  /// null when the stay is not ahead of us.
  static String? _countdown(DateTime checkIn) {
    final DateTime today = DateTime.now();
    final int days = DateTime(checkIn.year, checkIn.month, checkIn.day)
        .difference(DateTime(today.year, today.month, today.day))
        .inDays;
    if (days < 0) return null;
    if (days == 0) return 'Today';
    if (days == 1) return 'Tomorrow';
    return 'In $days days';
  }

  Widget _bookingCard(StayBooking b) {
    final StayListing? listing = _listings[b.listingId];
    final chip = _statusChip(b.status);
    final String? countdown =
        b.status.isCancelled || b.status == BookingStatus.declined
            ? null
            : _countdown(b.checkIn);

    final List<StayPhoto> photos =
        List<StayPhoto>.from(listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return InkWell(
      onTap: () => Navigator.of(context).pushNamed(
        StayRoutes.bookingDetails,
        arguments: <String, dynamic>{'bookingId': b.id},
      ),
      borderRadius: BorderRadius.circular(16),
      child: Container(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.04),
              blurRadius: 10,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            ClipRRect(
              borderRadius:
                  const BorderRadius.vertical(top: Radius.circular(16)),
              child: photos.isEmpty
                  ? Container(
                      height: 180,
                      width: double.infinity,
                      color: GoOutsColors.paleBlueTint,
                      child: const Icon(Icons.home_outlined,
                          size: 44, color: GoOutsColors.primaryBlue),
                    )
                  : Image.network(
                      photos.first.url,
                      height: 180,
                      width: double.infinity,
                      fit: BoxFit.cover,
                      errorBuilder: (_, __, ___) => Container(
                        height: 180,
                        width: double.infinity,
                        color: GoOutsColors.paleBlueTint,
                        child: const Icon(Icons.home_outlined,
                            size: 44, color: GoOutsColors.primaryBlue),
                      ),
                    ),
            ),
            Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: Text(
                          // Falls back to the reference while the listing
                          // loads, so the card is never nameless.
                          listing?.title ?? 'Booking ${b.id}',
                          overflow: TextOverflow.ellipsis,
                          style: GoogleFonts.inter(
                            fontSize: 18,
                            fontWeight: FontWeight.bold,
                            color: GoOutsColors.deepNavy,
                          ),
                        ),
                      ),
                      if (countdown != null) ...[
                        const SizedBox(width: 8),
                        Text(
                          countdown,
                          style: GoogleFonts.inter(
                            fontSize: 14,
                            fontWeight: FontWeight.w500,
                            color: GoOutsColors.primaryBlue,
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 4),
                  Text(
                    '${_dateRange(b.checkIn, b.checkOut)} · '
                    '${b.nights} ${b.nights == 1 ? 'night' : 'nights'}',
                    style: GoogleFonts.inter(
                        fontSize: 15, color: GoOutsColors.bodyText),
                  ),
                  if ((listing?.address.town ?? '').isNotEmpty)
                    Text(
                      listing!.address.town,
                      style: GoogleFonts.inter(
                          fontSize: 15, color: GoOutsColors.bodyText),
                    ),
                  const SizedBox(height: 16),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 12, vertical: 6),
                        decoration: BoxDecoration(
                          color: chip.colour.withValues(alpha: 0.1),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Text(
                          chip.label,
                          style: GoogleFonts.inter(
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                            color: chip.colour,
                            letterSpacing: 0.5,
                          ),
                        ),
                      ),
                      Text(
                        'View details',
                        style: GoogleFonts.inter(
                          fontSize: 14,
                          fontWeight: FontWeight.bold,
                          color: GoOutsColors.primaryBlue,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
